// static inline int floatstring(const char * p); mpstime.cpp
// file-static twin of the interp-arith.cpp:597 body - PRIVATE
// here (see header: the Stubs member seat stays with its
// below-roster owner).
private fun floatstring(p: CharArray): Boolean {
    var f = 0
    var ix = 0
    while (ix < p.size && p[ix] != NUL) {
        val c = p[ix]
        if (c.isDigit() || c == '-' || c == '+') {
            ix++
            continue
        }
        if (c == '.' || c.lowercaseChar() == 'e') {
            f = 1
            ix++
            continue
        }
        return false
    }
    return f != 0
}

// inline int numcomp2(unsigned char * aa)
fun numcomp2(aa: CharArray): Int {
    // if (floatstring((char *) aa)) return (atof(aa) != 0.0);
    if (floatstring(aa)) {
        return if (strtod(CstringOps.cstring(aa)) != 0.0) 1 else 0
    }
    // return atoi(aa);
    return atoi(CstringOps.cstring(aa))
}

// inline char * strxcat(char * a, char * b) - concatenate b
// onto a at the NUL; the pointer-advance folds to the index
// cursor (H-016).
fun strxcat(a: CharArray, b: CharArray): CharArray {
    var ix = 0
    while (ix < a.size && a[ix] != NUL) ix++
    var j = 0
    while (j < b.size && b[j] != NUL) {
        a[ix] = b[j]
        ix++
        j++
    }
    return a
}

// inline char * strcatz(char * out, char * in) - append in at
// the NUL, then the CHAR_1 (\u0001) delimiter byte and a NUL
// (the vendor *(out++) = '\u0001'; *out = 0; sequence kept
// verbatim; the pointer-advance folds to the index cursor).
fun strcatz(out: CharArray, inn: CharArray): CharArray {
    var ix = 0
    while (ix < out.size && out[ix] != NUL) ix++
    var j = 0
    while (j < inn.size && inn[j] != NUL) {
        out[ix] = inn[j]
        ix++
        j++
    }
    out[ix] = CHAR_1
    ix++
    if (ix < out.size) out[ix] = NUL
    return out
}

